def check_age(age):
    if age < 0:
        raise ValueError("возраст отрицательный")
    return age

class TestAge(unittest.TestCase):
    def test_valid(self):
        self.assertEqual(check_age(20), 20)

    def test_negative(self):
        with self.assertRaises(ValueError):
            check_age(-1)


run(TestAge)

