class Cart:
    def __init__(self):
        self.items = []

    def add(self, name):
        self.items.append(name)

class TestCart(unittest.TestCase):
    def setUp(self):
        self.cart = Cart()

    def test_empty(self):
        self.assertEqual(len(self.cart.items), 0)

    def test_add(self):
        self.cart.add("хлеб")
        self.assertEqual(self.cart.items, ["хлеб"])


run(TestCart)
